# Test the ratios found
ratios = [
    (6, 1),
    (15, 2),
    (28, 3),
    (45, 4)
]

def calculate_E(c, d):
    return (c*c + d*d) / (c*d)

results = {}
for c, d in ratios:
    E = calculate_E(c, d)
    results[(c, d)] = E

print("Ratios found:")
for pair, E in results.items():
    print(f"Pair {pair}: E = {E} (Decimal: {E:.4f})")

# Find the minimum
min_E = min(results.values())
print(f"Minimum E found: {min_E} (Decimal: {min_E:.4f})")
